import { useEffect, useState } from "react";
import Cards from "../../components/Cards/Cards";
import ProdCategory from "../../components/ProdCategory/ProdCategory";

import "./Products.css";

export const Products = () => {
  const [data, setData] = useState([]);
  useEffect(() => {
    fetch("https://fakestoreapi.com/products")
      .then((res) => res.json())
      .then((res) => setData(res));
  });

  console.log(data.category);


  let unique = [];
  if (!unique.includes(data.category)) {
    unique.push(data.category);
  }

  console.log(unique);

  return (
    <div className="mainProducts">
      <div className="category">
        <button>All</button>
        {data.map((elm, i) => {
          return <ProdCategory key={i} category={elm.category} />;
        })}
      </div>
      <div className="aaaa">
        {data.map((elm, i) => {
          return (
            <Cards
              key={i}
              image={elm.image}
              title={elm.title}
              price={elm.price}
            />
          );
        })}
      </div>
    </div>
  );
};
